foreach($rows as $row){$_GET=['date'=>$row['day'],'month'=>'2026-10'];$seen=booking_routes($a,'/bookings',[],'GET')[1];ensure($seen['total']===$adminRows[$row['day']]['total'],'Employee and Admin see same calendar count on '.$row['day']);$found=array_values(array_filter($seen['rows'],fn($r)=>$r['id']===$row['id']));ensure(count($found)===1,'Employee sees unassigned / colleague / own booking');ensure(!array_intersect(['customer_phone','note','source_sheet','source_row'],array_keys($found[0])),'Employee cannot retrieve restricted customer/source fields');}
