$_GET=['scope'=>'mine','start'=>'2026-10-19','end'=>'2026-10-31'];$mine=booking_routes($a,'/bookings/summary',[],'GET')[1];ensure($mine['scope']==='my_bookings','Own summary labelled');ensure($mine['active']<$adminSummary['active'],'Own subset excludes unassigned and colleague');
